FILES = json.loads("{\"pyproject.toml\":\"[project]\\nname=\\\"alerta-tempestade-backend\\\"\\nversion=\\\"1.0.0\\\"\\nrequires-python=\\\">=3.11\\\"\\ndependencies=[\\n \\\"fastapi>=0.115,<1\\\",\\\"uvicorn[standard]>=0.30,<1\\\",\\\"sqlalchemy>=2,<3\\\",\\n \\\"pydantic-settings>=2,<3\\\",\\\"pyjwt>=2.8,<3\\\",\\\"pwdlib[argon2]>=0.2,<1\\\",\\n \\\"email-validator>=2,<3\\\",\\\"python-multipart>=0.0.9,<1\\\",\\\"psycopg[binary]>=3.1,<4\\\"\\n]\\n[project.optional-dependencies]\\ntest=[\\\"pytest>=8,<9\\\",\\\"httpx>=0.27,<1\\\"]\\n[tool.pytest.ini_options]\\ntestpaths=[\\\"tests\\\"]\\n\",\".env.example\":\"# Development example. Never expose action tokens or example credentials in production.\\nDATABASE_URL=sqlite:///./alerta_tempestade.db\\nAPP_SECRET_KEY=replace-with-at-least-32-random-characters\\nACCESS_TOKEN_MINUTES=30\\nEXPOSE_DEV_TOKENS=true\\nFRONTEND_BASE_URL=http://localhost:3000\\nSMTP_HOST=\\nSMTP_PORT=587\\nSMTP_USERNAME=\\nSMTP_PASSWORD=\\nSMTP_FROM=\\nCORS_ORIGINS=http://localhost:3000,http://localhost:5173\\nBOOTSTRAP_OWNER_NAME=Owner\\nBOOTSTRAP_OWNER_EMAIL=owner@example.com\\nBOOTSTRAP_OWNER_PASSWORD=ChangeMe!123\\nAUTO_CREATE_TABLES=true\\n\",\".gitignore\":\".env\\n.venv/\\n__pycache__/\\n*.py[cod]\\n*.db\\n.pytest_cache/\\n\",\"Dockerfile\":\"FROM python:3.11-slim\\nWORKDIR /app\\nCOPY pyproject.toml .\\nCOPY app ./app\\nRUN pip install --no-cache-dir .\\nENV AUTO_CREATE_TABLES=true\\nEXPOSE 8000\\nCMD [\\\"uvicorn\\\",\\\"app.main:app\\\",\\\"--host\\\",\\\"0.0.0.0\\\",\\\"--port\\\",\\\"8000\\\"]\\n\",\"compose.yaml\":\"services:\\n  db:\\n    image: postgres:16-alpine\\n    environment:\\n      POSTGRES_DB: alerta_tempestade\\n      POSTGRES_USER: alerta\\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?set POSTGRES_PASSWORD}\\n    healthcheck:\\n      test: [\\\"CMD-SHELL\\\", \\\"pg_isready -U alerta -d alerta_tempestade\\\"]\\n      interval: 5s\\n      timeout: 5s\\n      retries: 12\\n    volumes: [postgres_data:/var/lib/postgresql/data]\\n  api:\\n    build: .\\n    ports: [\\\"127.0.0.1:8000:8000\\\"]\\n    restart: on-failure\\n    environment:\\n      DATABASE_URL: postgresql+psycopg://alerta:${POSTGRES_PASSWORD}@db:5432/alerta_tempestade\\n      APP_SECRET_KEY: ${APP_SECRET_KEY:?set APP_SECRET_KEY}\\n      BOOTSTRAP_OWNER_NAME: ${BOOTSTRAP_OWNER_NAME:-Owner}\\n      BOOTSTRAP_OWNER_EMAIL: ${BOOTSTRAP_OWNER_EMAIL:?set BOOTSTRAP_OWNER_EMAIL}\\n      BOOTSTRAP_OWNER_PASSWORD: ${BOOTSTRAP_OWNER_PASSWORD:?set BOOTSTRAP_OWNER_PASSWORD}\\n      EXPOSE_DEV_TOKENS: ${EXPOSE_DEV_TOKENS:-false}\\n      FRONTEND_BASE_URL: ${FRONTEND_BASE_URL:-http://localhost:3000}\\n      SMTP_HOST: ${SMTP_HOST:-}\\n      SMTP_PORT: ${SMTP_PORT:-587}\\n      SMTP_USERNAME: ${SMTP_USERNAME:-}\\n      SMTP_PASSWORD: ${SMTP_PASSWORD:-}\\n      SMTP_FROM: ${SMTP_FROM:-}\\n      AUTO_CREATE_TABLES: \\\"true\\\"\\n      CORS_ORIGINS: http://localhost:3000,http://localhost:5173\\n    depends_on:\\n      db:\\n        condition: service_healthy\\nvolumes:\\n  postgres_data:\\n\",\"app/__init__.py\":\"\",\"app/main.py\":\"from __future__ import annotations\\nimport hashlib, secrets, smtplib\\nfrom email.message import EmailMessage\\nfrom contextlib import asynccontextmanager\\nfrom datetime import UTC, datetime, timedelta\\nfrom enum import StrEnum\\nfrom typing import Annotated, Any, Literal\\nimport jwt\\nfrom fastapi import Depends, FastAPI, HTTPException, Query, Response\\nfrom fastapi.middleware.cors import CORSMiddleware\\nfrom fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm\\nfrom pydantic import BaseModel, ConfigDict, EmailStr, Field, HttpUrl, model_validator\\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\\nfrom pwdlib import PasswordHash\\nfrom sqlalchemy import Boolean, DateTime, ForeignKey, Integer, JSON, String, Text, UniqueConstraint, create_engine, event, or_, select, update\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column, sessionmaker\\n\\ndef utcnow(): return datetime.now(UTC)\\ndef as_utc(v):\\n    return v.replace(tzinfo=UTC) if v.tzinfo is None else v.astimezone(UTC)\\n\\nclass Settings(BaseSettings):\\n    model_config=SettingsConfigDict(env_file=\\\".env\\\",extra=\\\"ignore\\\")\\n    database_url:str=\\\"sqlite:///./alerta_tempestade.db\\\"\\n    app_secret_key:str=\\\"development-only-change-me-please\\\"\\n    access_token_minutes:int=30\\n    expose_dev_tokens:bool=False\\n    frontend_base_url:str=\\\"http://localhost:3000\\\"\\n    smtp_host:str|None=None\\n    smtp_port:int=587\\n    smtp_username:str|None=None\\n    smtp_password:str|None=None\\n    smtp_from:str|None=None\\n    cors_origins:str=\\\"\\\"\\n    bootstrap_owner_name:str|None=None\\n    bootstrap_owner_email:EmailStr|None=None\\n    bootstrap_owner_password:str|None=None\\n    auto_create_tables:bool=True\\n    issuer:str=\\\"alerta-tempestade-api\\\"\\n    audience:str=\\\"alerta-tempestade-frontend\\\"\\nsettings=Settings()\\nif (settings.app_secret_key==\\\"development-only-change-me-please\\\" or len(settings.app_secret_key.encode())<32) and not settings.expose_dev_tokens:\\n    raise RuntimeError(\\\"Configure an APP_SECRET_KEY containing at least 32 bytes\\\")\\nif not settings.expose_dev_tokens and not (settings.smtp_host and settings.smtp_from):\\n    raise RuntimeError(\\\"Configure SMTP delivery or explicitly enable development token exposure\\\")\\nargs={\\\"check_same_thread\\\":False} if settings.database_url.startswith(\\\"sqlite\\\") else {}\\nengine=create_engine(settings.database_url,connect_args=args,pool_pre_ping=True)\\nif settings.database_url.startswith(\\\"sqlite\\\"):\\n    @event.listens_for(engine,\\\"connect\\\")\\n    def _fk(conn,_):\\n        cur=conn.cursor(); cur.execute(\\\"PRAGMA foreign_keys=ON\\\"); cur.close()\\nSessionLocal=sessionmaker(bind=engine,expire_on_commit=False)\\nclass Base(DeclarativeBase): pass\\n\\nclass Role(StrEnum): USER=\\\"USER\\\"; METEOROLOGIST=\\\"METEOROLOGIST\\\"; OWNER=\\\"OWNER\\\"\\nclass AlertType(StrEnum): SEVERE_STORM=\\\"SEVERE_STORM\\\"; TORNADO=\\\"TORNADO\\\"\\nclass Severity(StrEnum): LOW=\\\"LOW\\\"; MODERATE=\\\"MODERATE\\\"; HIGH=\\\"HIGH\\\"; EXTREME=\\\"EXTREME\\\"\\nclass ReportStatus(StrEnum): PENDING=\\\"PENDING\\\"; VERIFIED=\\\"VERIFIED\\\"; REJECTED=\\\"REJECTED\\\"\\n\\nclass User(Base):\\n    __tablename__=\\\"users\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    name:Mapped[str]=mapped_column(String(100))\\n    email:Mapped[str]=mapped_column(String(320),unique=True,index=True)\\n    password_hash:Mapped[str]=mapped_column(String(512))\\n    role:Mapped[str]=mapped_column(String(24),default=Role.USER.value,index=True)\\n    is_verified:Mapped[bool]=mapped_column(Boolean,default=False)\\n    is_active:Mapped[bool]=mapped_column(Boolean,default=True)\\n    token_version:Mapped[int]=mapped_column(Integer,default=0)\\n    created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow)\\nclass ActionToken(Base):\\n    __tablename__=\\\"action_tokens\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    user_id:Mapped[int]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"CASCADE\\\"),index=True)\\n    purpose:Mapped[str]=mapped_column(String(32),index=True)\\n    token_hash:Mapped[str]=mapped_column(String(64),unique=True,index=True)\\n    expires_at:Mapped[datetime]=mapped_column(DateTime(timezone=True))\\n    context_hash:Mapped[str|None]=mapped_column(String(64),nullable=True)\\n    used_at:Mapped[datetime|None]=mapped_column(DateTime(timezone=True),nullable=True)\\nclass News(Base):\\n    __tablename__=\\\"news\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    title:Mapped[str]=mapped_column(String(200)); description:Mapped[str]=mapped_column(Text)\\n    image_url:Mapped[str|None]=mapped_column(String(2048),nullable=True)\\n    video_url:Mapped[str|None]=mapped_column(String(2048),nullable=True)\\n    reference_url:Mapped[str]=mapped_column(String(2048))\\n    author_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True)\\n    created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow)\\n    updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,onupdate=utcnow)\\nclass Forecast(Base):\\n    __tablename__=\\\"forecasts\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    issued_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,index=True)\\n    valid_until:Mapped[datetime]=mapped_column(DateTime(timezone=True),index=True)\\n    severity:Mapped[str]=mapped_column(String(24)); description:Mapped[str]=mapped_column(Text)\\n    area:Mapped[dict[str,Any]]=mapped_column(JSON)\\n    author_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True)\\n    updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,onupdate=utcnow)\\nclass Alert(Base):\\n    __tablename__=\\\"alerts\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    alert_type:Mapped[str]=mapped_column(String(24),index=True)\\n    issued_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,index=True)\\n    valid_until:Mapped[datetime]=mapped_column(DateTime(timezone=True),index=True)\\n    description:Mapped[str]=mapped_column(Text); safety_instructions:Mapped[str]=mapped_column(Text)\\n    area:Mapped[dict[str,Any]]=mapped_column(JSON)\\n    author_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True)\\nclass LocationSubscription(Base):\\n    __tablename__=\\\"location_subscriptions\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    user_id:Mapped[int]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"CASCADE\\\"),unique=True)\\n    longitude:Mapped[float]; latitude:Mapped[float]\\n    enabled:Mapped[bool]=mapped_column(Boolean,default=True)\\n    updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,onupdate=utcnow)\\nclass Notification(Base):\\n    __tablename__=\\\"notifications\\\"\\n    __table_args__=(UniqueConstraint(\\\"user_id\\\",\\\"alert_id\\\",name=\\\"uq_notification_user_alert\\\"),)\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    user_id:Mapped[int]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"CASCADE\\\"),index=True)\\n    alert_id:Mapped[int]=mapped_column(ForeignKey(\\\"alerts.id\\\",ondelete=\\\"CASCADE\\\"),index=True)\\n    message:Mapped[str]=mapped_column(String(500))\\n    read_at:Mapped[datetime|None]=mapped_column(DateTime(timezone=True),nullable=True)\\n    created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow)\\nclass WeatherReport(Base):\\n    __tablename__=\\\"weather_reports\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    user_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True,index=True)\\n    description:Mapped[str]=mapped_column(Text); location_name:Mapped[str]=mapped_column(String(200))\\n    longitude:Mapped[float]; latitude:Mapped[float]\\n    event_at:Mapped[datetime]=mapped_column(DateTime(timezone=True))\\n    image_url:Mapped[str|None]=mapped_column(String(2048),nullable=True)\\n    review_status:Mapped[str]=mapped_column(String(24),default=ReportStatus.PENDING.value,index=True)\\n    reviewer_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True)\\n    reviewed_at:Mapped[datetime|None]=mapped_column(DateTime(timezone=True),nullable=True)\\n    review_notes:Mapped[str|None]=mapped_column(Text,nullable=True)\\n    created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow)\\nclass EducationArticle(Base):\\n    __tablename__=\\\"education_articles\\\"\\n    id:Mapped[int]=mapped_column(Integer,primary_key=True)\\n    title:Mapped[str]=mapped_column(String(200)); body:Mapped[str]=mapped_column(Text)\\n    image_url:Mapped[str|None]=mapped_column(String(2048),nullable=True)\\n    video_url:Mapped[str|None]=mapped_column(String(2048),nullable=True)\\n    reference_url:Mapped[str]=mapped_column(String(2048))\\n    author_id:Mapped[int|None]=mapped_column(ForeignKey(\\\"users.id\\\",ondelete=\\\"SET NULL\\\"),nullable=True)\\n    created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow)\\n    updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=utcnow,onupdate=utcnow)\\n\\nph=PasswordHash.recommended(); oauth2=OAuth2PasswordBearer(tokenUrl=\\\"/auth/login\\\")\\ndef get_db():\\n    with SessionLocal() as db: yield db\\nDb=Annotated[Session,Depends(get_db)]\\ndef email_key(v):\\n    local,domain=v.strip().rsplit(\\\"@\\\",1); return f\\\"{local.casefold()}@{domain.casefold()}\\\"\\ndef valid_password(v):\\n    special=set(\\\"!@#$%^&*()_+-=[]{}|;:,.<>?/~\\\")\\n    if len(v)<6 or not any(c.isupper() for c in v) or not any(c in special for c in v):\\n        raise HTTPException(422,\\\"Password needs 6+ characters, one uppercase letter and one special character\\\")\\ndef issue_token(db,u,purpose,minutes):\\n    now=utcnow()\\n    db.execute(update(ActionToken).where(ActionToken.user_id==u.id,ActionToken.purpose==purpose,ActionToken.used_at.is_(None)).values(used_at=now))\\n    raw=secrets.token_urlsafe(32)\\n    context=hashlib.sha256(u.email.encode()).hexdigest() if purpose==\\\"verify\\\" else None\\n    db.add(ActionToken(user_id=u.id,purpose=purpose,token_hash=hashlib.sha256(raw.encode()).hexdigest(),context_hash=context,expires_at=now+timedelta(minutes=minutes)))\\n    return raw\\ndef deliver_token(user,raw,purpose):\\n    if settings.expose_dev_tokens: return\\n    route=\\\"verify-email\\\" if purpose==\\\"verify\\\" else \\\"reset-password\\\"\\n    msg=EmailMessage()\\n    msg[\\\"Subject\\\"]=\\\"Alerta Tempestade - verify email\\\" if purpose==\\\"verify\\\" else \\\"Alerta Tempestade - reset password\\\"\\n    msg[\\\"From\\\"]=settings.smtp_from; msg[\\\"To\\\"]=user.email\\n    msg.set_content(f\\\"{settings.frontend_base_url.rstrip('/')}/{route}?token={raw}\\\")\\n    try:\\n        with smtplib.SMTP(settings.smtp_host,settings.smtp_port,timeout=10) as smtp:\\n            smtp.starttls()\\n            if settings.smtp_username: smtp.login(settings.smtp_username,settings.smtp_password or \\\"\\\")\\n            smtp.send_message(msg)\\n    except (smtplib.SMTPException,OSError):\\n        raise HTTPException(503,\\\"Email delivery failed; saved state can be recovered with the resend endpoint\\\")\\ndef redeem(db,raw,purpose):\\n    item=db.scalar(select(ActionToken).where(ActionToken.token_hash==hashlib.sha256(raw.encode()).hexdigest(),ActionToken.purpose==purpose,ActionToken.used_at.is_(None)))\\n    if not item or as_utc(item.expires_at)<utcnow(): raise HTTPException(400,\\\"Invalid or expired token\\\")\\n    u=db.get(User,item.user_id)\\n    if not u or not u.is_active: raise HTTPException(400,\\\"Invalid or expired token\\\")\\n    if purpose==\\\"verify\\\" and item.context_hash!=hashlib.sha256(u.email.encode()).hexdigest():\\n        raise HTTPException(400,\\\"Invalid or expired token\\\")\\n    result=db.execute(update(ActionToken).where(ActionToken.id==item.id,ActionToken.used_at.is_(None)).values(used_at=utcnow()))\\n    if result.rowcount!=1: raise HTTPException(400,\\\"Invalid or expired token\\\")\\n    return u\\ndef access_token(u):\\n    now=utcnow()\\n    return jwt.encode({\\\"sub\\\":str(u.id),\\\"ver\\\":u.token_version,\\\"type\\\":\\\"access\\\",\\\"iat\\\":now,\\\"exp\\\":now+timedelta(minutes=settings.access_token_minutes),\\\"iss\\\":settings.issuer,\\\"aud\\\":settings.audience},settings.app_secret_key,algorithm=\\\"HS256\\\")\\ndef current_user(token:Annotated[str,Depends(oauth2)],db:Db):\\n    err=HTTPException(401,\\\"Invalid or expired credentials\\\",headers={\\\"WWW-Authenticate\\\":\\\"Bearer\\\"})\\n    try:\\n        p=jwt.decode(token,settings.app_secret_key,algorithms=[\\\"HS256\\\"],issuer=settings.issuer,audience=settings.audience,options={\\\"require\\\":[\\\"sub\\\",\\\"exp\\\",\\\"iat\\\",\\\"iss\\\",\\\"aud\\\",\\\"type\\\"]})\\n        if p[\\\"type\\\"]!=\\\"access\\\": raise err\\n        u=db.get(User,int(p[\\\"sub\\\"]))\\n    except (jwt.PyJWTError,ValueError,TypeError,KeyError): raise err\\n    if not u or not u.is_active or not u.is_verified or p.get(\\\"ver\\\")!=u.token_version: raise err\\n    return u\\nCurrent=Annotated[User,Depends(current_user)]\\ndef staff(u:Current):\\n    if u.role not in (Role.METEOROLOGIST.value,Role.OWNER.value): raise HTTPException(403,\\\"Meteorologist access required\\\")\\n    return u\\nStaff=Annotated[User,Depends(staff)]\\ndef get(db,model,item_id):\\n    item=db.get(model,item_id)\\n    if not item: raise HTTPException(404,\\\"Resource not found\\\")\\n    return item\\ndef page(db,stmt,limit,offset): return list(db.scalars(stmt.limit(limit).offset(offset)))\\ndef http_url(v):\\n    if v is None:return None\\n    try: HttpUrl(v)\\n    except ValueError: raise HTTPException(422,\\\"Invalid HTTP(S) URL\\\")\\n    return v\\n\\nclass Polygon(BaseModel):\\n    type:Literal[\\\"Polygon\\\"]=\\\"Polygon\\\"\\n    coordinates:list[list[tuple[float,float]]]\\n    @model_validator(mode=\\\"after\\\")\\n    def check(self):\\n        if not self.coordinates: raise ValueError(\\\"Exterior ring required\\\")\\n        total=0\\n        for ring in self.coordinates:\\n            if len(ring)<4 or ring[0]!=ring[-1]: raise ValueError(\\\"Rings need 4+ positions and closure\\\")\\n            total+=len(ring)\\n            for lon,lat in ring:\\n                if not(-180<=lon<=180 and -90<=lat<=90): raise ValueError(\\\"Use WGS84 [longitude, latitude]\\\")\\n        if total>10000: raise ValueError(\\\"Polygon has too many positions\\\")\\n        return self\\ndef on_segment(x,y,a,b):\\n    cross=(y-a[1])*(b[0]-a[0])-(x-a[0])*(b[1]-a[1])\\n    return abs(cross)<1e-10 and min(a[0],b[0])-1e-10<=x<=max(a[0],b[0])+1e-10 and min(a[1],b[1])-1e-10<=y<=max(a[1],b[1])+1e-10\\ndef in_ring(x,y,ring):\\n    inside=False\\n    for i in range(len(ring)-1):\\n        a,b=ring[i],ring[i+1]\\n        if on_segment(x,y,a,b): return True\\n        if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]: inside=not inside\\n    return inside\\ndef in_polygon(x,y,p):\\n    rings=p[\\\"coordinates\\\"]; return in_ring(x,y,rings[0]) and not any(in_ring(x,y,h) for h in rings[1:])\\n\\nclass ORM(BaseModel): model_config=ConfigDict(from_attributes=True)\\nclass UserOut(ORM):\\n    id:int; name:str; email:EmailStr; role:Role; is_verified:bool; is_active:bool; created_at:datetime\\nclass RegisterIn(BaseModel):\\n    name:str=Field(min_length=2,max_length=100); email:EmailStr; password:str=Field(min_length=6,max_length=128)\\nclass TokenMessage(BaseModel): message:str; development_token:str|None=None\\nclass RawToken(BaseModel): token:str=Field(min_length=20)\\nclass ResetRequest(BaseModel): email:EmailStr\\nclass ResetIn(RawToken): new_password:str=Field(min_length=6,max_length=128)\\nclass LoginIn(BaseModel): email:EmailStr; password:str=Field(min_length=1,max_length=128)\\nclass LoginOut(BaseModel): access_token:str; token_type:Literal[\\\"bearer\\\"]=\\\"bearer\\\"; user:UserOut\\nclass UserPatch(BaseModel):\\n    name:str|None=Field(None,min_length=2,max_length=100); email:EmailStr|None=None; role:Role|None=None; is_active:bool|None=None\\nclass NewsIn(BaseModel):\\n    title:str=Field(min_length=1,max_length=200); description:str=Field(min_length=1,max_length=50000)\\n    image_url:str|None=Field(None,max_length=2048); video_url:str|None=Field(None,max_length=2048); reference_url:str=Field(min_length=1,max_length=2048)\\nclass NewsPatch(BaseModel):\\n    title:str|None=Field(None,min_length=1,max_length=200); description:str|None=Field(None,min_length=1,max_length=50000)\\n    image_url:str|None=Field(None,max_length=2048); video_url:str|None=Field(None,max_length=2048); reference_url:str|None=Field(None,max_length=2048)\\nclass NewsOut(NewsIn,ORM): id:int; author_id:int|None; created_at:datetime; updated_at:datetime\\nclass ForecastIn(BaseModel):\\n    valid_until:datetime; severity:Severity; description:str=Field(min_length=1,max_length=50000); area:Polygon\\n    @model_validator(mode=\\\"after\\\")\\n    def check(self):\\n        if self.valid_until.tzinfo is None or as_utc(self.valid_until)<=utcnow(): raise ValueError(\\\"valid_until must be timezone-aware and future\\\")\\n        return self\\nclass ForecastPatch(BaseModel):\\n    valid_until:datetime|None=None; severity:Severity|None=None; description:str|None=Field(None,min_length=1,max_length=50000); area:Polygon|None=None\\nclass ForecastOut(ORM):\\n    id:int; issued_at:datetime; valid_until:datetime; severity:Severity; description:str; area:dict[str,Any]; author_id:int|None; updated_at:datetime\\nclass AlertIn(BaseModel):\\n    alert_type:AlertType; valid_until:datetime; description:str=Field(min_length=1,max_length=50000); area:Polygon\\n    @model_validator(mode=\\\"after\\\")\\n    def check(self):\\n        if self.valid_until.tzinfo is None or as_utc(self.valid_until)<=utcnow(): raise ValueError(\\\"valid_until must be timezone-aware and future\\\")\\n        return self\\nclass AlertOut(ORM):\\n    id:int; alert_type:AlertType; issued_at:datetime; valid_until:datetime; description:str; safety_instructions:str; area:dict[str,Any]; author_id:int|None\\nclass SubscriptionIn(BaseModel):\\n    longitude:float=Field(ge=-180,le=180); latitude:float=Field(ge=-90,le=90); enabled:bool=True\\nclass SubscriptionOut(SubscriptionIn,ORM): updated_at:datetime\\nclass NotificationOut(ORM):\\n    id:int; alert_id:int; message:str; read_at:datetime|None; created_at:datetime\\nclass ReportIn(BaseModel):\\n    description:str=Field(min_length=1,max_length=50000); location_name:str=Field(min_length=1,max_length=200)\\n    longitude:float=Field(ge=-180,le=180); latitude:float=Field(ge=-90,le=90); event_at:datetime; image_url:str|None=Field(None,max_length=2048)\\n    @model_validator(mode=\\\"after\\\")\\n    def check(self):\\n        if self.event_at.tzinfo is None or as_utc(self.event_at)>utcnow()+timedelta(minutes=5): raise ValueError(\\\"event_at must be timezone-aware and not future\\\")\\n        return self\\nclass ReviewIn(BaseModel): review_status:Literal[ReportStatus.VERIFIED,ReportStatus.REJECTED]; review_notes:str|None=Field(None,max_length=10000)\\nclass ReportOut(ORM):\\n    id:int; user_id:int|None; description:str; location_name:str; longitude:float; latitude:float; event_at:datetime\\n    image_url:str|None; review_status:ReportStatus; reviewer_id:int|None; reviewed_at:datetime|None; review_notes:str|None; created_at:datetime\\nclass EducationIn(BaseModel):\\n    title:str=Field(min_length=1,max_length=200); body:str=Field(min_length=1,max_length=100000)\\n    image_url:str|None=Field(None,max_length=2048); video_url:str|None=Field(None,max_length=2048); reference_url:str=Field(min_length=1,max_length=2048)\\nclass EducationPatch(BaseModel):\\n    title:str|None=Field(None,min_length=1,max_length=200); body:str|None=Field(None,min_length=1,max_length=100000)\\n    image_url:str|None=Field(None,max_length=2048); video_url:str|None=Field(None,max_length=2048); reference_url:str|None=Field(None,min_length=1,max_length=2048)\\nclass EducationOut(EducationIn,ORM): id:int; author_id:int|None; created_at:datetime; updated_at:datetime\\n\\ndef auth(db,email,password):\\n    u=db.scalar(select(User).where(User.email==email_key(email)))\\n    if not u or not u.is_active or not ph.verify(password,u.password_hash): raise HTTPException(401,\\\"Incorrect email or password\\\")\\n    if not u.is_verified: raise HTTPException(403,\\\"Email not verified\\\")\\n    return u\\ndef media(obj):\\n    for f in (\\\"image_url\\\",\\\"video_url\\\",\\\"reference_url\\\"):\\n        if hasattr(obj,f): setattr(obj,f,http_url(getattr(obj,f)))\\n\\n@asynccontextmanager\\nasync def lifespan(_):\\n    if settings.auto_create_tables: Base.metadata.create_all(engine)\\n    with SessionLocal() as db:\\n        if settings.bootstrap_owner_email and settings.bootstrap_owner_password:\\n            valid_password(settings.bootstrap_owner_password); key=email_key(str(settings.bootstrap_owner_email))\\n            if not db.scalar(select(User).where(User.email==key)):\\n                db.add(User(name=settings.bootstrap_owner_name or \\\"Owner\\\",email=key,password_hash=ph.hash(settings.bootstrap_owner_password),role=Role.OWNER.value,is_verified=True)); db.commit()\\n    yield\\napp=FastAPI(title=\\\"Alerta Tempestade API\\\",version=\\\"1.0.0\\\",lifespan=lifespan)\\norigins=[x.strip() for x in settings.cors_origins.split(\\\",\\\") if x.strip()]\\nif origins: app.add_middleware(CORSMiddleware,allow_origins=origins,allow_methods=[\\\"*\\\"],allow_headers=[\\\"*\\\"])\\n@app.get(\\\"/health\\\")\\ndef health(): return {\\\"status\\\":\\\"ok\\\"}\\n@app.get(\\\"/ready\\\")\\ndef ready(db:Db):\\n    db.execute(select(1)); return {\\\"status\\\":\\\"ready\\\"}\\n\\n@app.post(\\\"/auth/register\\\",response_model=TokenMessage,status_code=202)\\ndef register(d:RegisterIn,db:Db):\\n    valid_password(d.password); key=email_key(str(d.email))\\n    if db.scalar(select(User).where(User.email==key)): raise HTTPException(409,\\\"Email already registered\\\")\\n    u=User(name=d.name.strip(),email=key,password_hash=ph.hash(d.password)); db.add(u); db.flush()\\n    raw=issue_token(db,u,\\\"verify\\\",1440)\\n    try: db.commit()\\n    except IntegrityError:\\n        db.rollback(); raise HTTPException(409,\\\"Email already registered\\\")\\n    deliver_token(u,raw,\\\"verify\\\")\\n    return TokenMessage(message=\\\"Verification instructions created\\\",development_token=raw if settings.expose_dev_tokens else None)\\n@app.post(\\\"/auth/verify-email\\\",response_model=TokenMessage)\\ndef verify(d:RawToken,db:Db):\\n    u=redeem(db,d.token,\\\"verify\\\"); u.is_verified=True; db.commit(); return TokenMessage(message=\\\"Email verified\\\")\\n@app.post(\\\"/auth/login\\\",response_model=LoginOut)\\ndef login(form:Annotated[OAuth2PasswordRequestForm,Depends()],db:Db):\\n    u=auth(db,form.username,form.password); return LoginOut(access_token=access_token(u),user=u)\\n@app.post(\\\"/auth/login-json\\\",response_model=LoginOut)\\ndef login_json(d:LoginIn,db:Db):\\n    u=auth(db,str(d.email),d.password); return LoginOut(access_token=access_token(u),user=u)\\n@app.post(\\\"/auth/resend-verification\\\",response_model=TokenMessage,status_code=202)\\ndef resend(d:ResetRequest,db:Db):\\n    u=db.scalar(select(User).where(User.email==email_key(str(d.email)),User.is_active.is_(True),User.is_verified.is_(False))); raw=None\\n    if u:\\n        raw=issue_token(db,u,\\\"verify\\\",1440); db.commit(); deliver_token(u,raw,\\\"verify\\\")\\n    return TokenMessage(message=\\\"If verification is pending, instructions were created\\\",development_token=raw if settings.expose_dev_tokens else None)\\n@app.post(\\\"/auth/forgot-password\\\",response_model=TokenMessage,status_code=202)\\ndef forgot(d:ResetRequest,db:Db):\\n    u=db.scalar(select(User).where(User.email==email_key(str(d.email)),User.is_active.is_(True))); raw=None\\n    if u:\\n        raw=issue_token(db,u,\\\"reset\\\",30); db.commit(); deliver_token(u,raw,\\\"reset\\\")\\n    return TokenMessage(message=\\\"If the account exists, reset instructions were created\\\",development_token=raw if settings.expose_dev_tokens else None)\\n@app.post(\\\"/auth/reset-password\\\",response_model=TokenMessage)\\ndef reset(d:ResetIn,db:Db):\\n    valid_password(d.new_password); u=redeem(db,d.token,\\\"reset\\\")\\n    db.execute(update(ActionToken).where(ActionToken.user_id==u.id,ActionToken.purpose==\\\"reset\\\",ActionToken.used_at.is_(None)).values(used_at=utcnow()))\\n    u.password_hash=ph.hash(d.new_password); u.token_version+=1; db.commit()\\n    return TokenMessage(message=\\\"Password reset\\\")\\n@app.get(\\\"/users/me\\\",response_model=UserOut)\\ndef me(u:Current): return u\\n\\n@app.get(\\\"/admin/users\\\",response_model=list[UserOut])\\ndef users(db:Db,_:Staff,q:str=Query(\\\"\\\",max_length=320),limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    s=select(User).order_by(User.id)\\n    if _.role==Role.METEOROLOGIST.value: s=s.where(User.role==Role.USER.value)\\n    if q:\\n        pat=f\\\"%{q.strip()}%\\\"\\n        s=s.where(or_(User.name.ilike(pat),User.email.ilike(pat),User.id==int(q)) if q.isdigit() else or_(User.name.ilike(pat),User.email.ilike(pat)))\\n    return page(db,s,limit,offset)\\n@app.patch(\\\"/admin/users/{uid}\\\",response_model=UserOut)\\ndef user_patch(uid:int,d:UserPatch,db:Db,actor:Staff):\\n    target=get(db,User,uid)\\n    if actor.role==Role.METEOROLOGIST.value and target.role!=Role.USER.value: raise HTTPException(403,\\\"Meteorologists manage users only\\\")\\n    values=d.model_dump(exclude_unset=True)\\n    if any(v is None for v in values.values()): raise HTTPException(422,\\\"Explicit null is not allowed\\\")\\n    if target.id==actor.id and values.get(\\\"is_active\\\") is False: raise HTTPException(409,\\\"Owner/staff cannot self-deactivate\\\")\\n    if \\\"role\\\" in values:\\n        if actor.role!=Role.OWNER.value: raise HTTPException(403,\\\"Only owner changes roles\\\")\\n        if target.id==actor.id and values[\\\"role\\\"]!=Role.OWNER: raise HTTPException(409,\\\"Owner cannot self-demote\\\")\\n        values[\\\"role\\\"]=values[\\\"role\\\"].value; target.token_version+=1\\n    if \\\"email\\\" in values:\\n        values[\\\"email\\\"]=email_key(str(values[\\\"email\\\"]))\\n        if db.scalar(select(User).where(User.email==values[\\\"email\\\"],User.id!=uid)): raise HTTPException(409,\\\"Email already registered\\\")\\n        target.is_verified=False; target.token_version+=1\\n    if \\\"is_active\\\" in values: target.token_version+=1\\n    for k,v in values.items(): setattr(target,k,v)\\n    raw=issue_token(db,target,\\\"verify\\\",1440) if \\\"email\\\" in values else None\\n    try: db.commit()\\n    except IntegrityError:\\n        db.rollback(); raise HTTPException(409,\\\"Conflicting user data\\\")\\n    if raw: deliver_token(target,raw,\\\"verify\\\")\\n    return target\\n@app.delete(\\\"/admin/users/{uid}\\\",status_code=204)\\ndef user_delete(uid:int,db:Db,actor:Staff):\\n    target=get(db,User,uid)\\n    if target.id==actor.id or target.role==Role.OWNER.value: raise HTTPException(409,\\\"Account cannot be deleted\\\")\\n    if actor.role==Role.METEOROLOGIST.value and target.role!=Role.USER.value: raise HTTPException(403,\\\"Meteorologists manage users only\\\")\\n    target.is_active=False; target.token_version+=1; target.email=f\\\"deleted+{target.id}-{secrets.token_hex(6)}@example.com\\\"; target.name=\\\"Deleted user\\\"; db.commit()\\n    return Response(status_code=204)\\n\\n@app.get(\\\"/news\\\",response_model=list[NewsOut])\\ndef news_list(db:Db,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)): return page(db,select(News).order_by(News.created_at.desc()),limit,offset)\\n@app.get(\\\"/news/{iid}\\\",response_model=NewsOut)\\ndef news_get(iid:int,db:Db): return get(db,News,iid)\\n@app.post(\\\"/news\\\",response_model=NewsOut,status_code=201)\\ndef news_create(d:NewsIn,db:Db,u:Staff):\\n    item=News(**d.model_dump(),author_id=u.id); media(item); db.add(item); db.commit(); return item\\n@app.patch(\\\"/news/{iid}\\\",response_model=NewsOut)\\ndef news_update(iid:int,d:NewsPatch,db:Db,_:Staff):\\n    item=get(db,News,iid); values=d.model_dump(exclude_unset=True)\\n    if any(values.get(k) is None for k in (\\\"title\\\",\\\"description\\\",\\\"reference_url\\\") if k in values): raise HTTPException(422,\\\"Title and description cannot be null\\\")\\n    for k,v in values.items(): setattr(item,k,v)\\n    media(item); item.updated_at=utcnow(); db.commit(); return item\\n@app.delete(\\\"/news/{iid}\\\",status_code=204)\\ndef news_delete(iid:int,db:Db,_:Staff):\\n    db.delete(get(db,News,iid)); db.commit(); return Response(status_code=204)\\n\\n@app.get(\\\"/forecasts\\\",response_model=list[ForecastOut])\\ndef forecast_list(db:Db,active_only:bool=True,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    s=select(Forecast).order_by(Forecast.issued_at.desc())\\n    if active_only:s=s.where(Forecast.valid_until>utcnow())\\n    return page(db,s,limit,offset)\\n@app.get(\\\"/forecasts/{iid}\\\",response_model=ForecastOut)\\ndef forecast_get(iid:int,db:Db): return get(db,Forecast,iid)\\n@app.post(\\\"/forecasts\\\",response_model=ForecastOut,status_code=201)\\ndef forecast_create(d:ForecastIn,db:Db,u:Staff):\\n    item=Forecast(valid_until=as_utc(d.valid_until),severity=d.severity.value,description=d.description,area=d.area.model_dump(mode=\\\"json\\\"),author_id=u.id)\\n    db.add(item); db.commit(); return item\\n@app.patch(\\\"/forecasts/{iid}\\\",response_model=ForecastOut)\\ndef forecast_update(iid:int,d:ForecastPatch,db:Db,_:Staff):\\n    item=get(db,Forecast,iid)\\n    if utcnow()>=as_utc(item.issued_at)+timedelta(minutes=30): raise HTTPException(409,\\\"Edit window closed\\\")\\n    values=d.model_dump(exclude_unset=True)\\n    if any(v is None for v in values.values()): raise HTTPException(422,\\\"Explicit null is not allowed\\\")\\n    if \\\"valid_until\\\" in values:\\n        if values[\\\"valid_until\\\"].tzinfo is None or as_utc(values[\\\"valid_until\\\"])<=utcnow(): raise HTTPException(422,\\\"valid_until must be timezone-aware and future\\\")\\n        values[\\\"valid_until\\\"]=as_utc(values[\\\"valid_until\\\"])\\n    if \\\"severity\\\" in values: values[\\\"severity\\\"]=values[\\\"severity\\\"].value\\n    if \\\"area\\\" in values: values[\\\"area\\\"]=d.area.model_dump(mode=\\\"json\\\")\\n    for k,v in values.items(): setattr(item,k,v)\\n    item.updated_at=utcnow(); db.commit(); return item\\n@app.delete(\\\"/forecasts/{iid}\\\",status_code=204)\\ndef forecast_delete(iid:int,db:Db,_:Staff):\\n    item=get(db,Forecast,iid)\\n    if utcnow()<as_utc(item.issued_at)+timedelta(minutes=30): raise HTTPException(409,\\\"Deletion allowed after 30 minutes\\\")\\n    db.delete(item); db.commit(); return Response(status_code=204)\\n\\nINSTRUCTIONS={\\n AlertType.SEVERE_STORM.value:\\\"Stay indoors, avoid windows and flooded roads, and follow official guidance.\\\",\\n AlertType.TORNADO.value:\\\"Seek a small interior room on the lowest floor, protect your head, and follow official guidance.\\\"\\n}\\n@app.get(\\\"/alerts\\\",response_model=list[AlertOut])\\ndef alert_list(db:Db,active_only:bool=True,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    s=select(Alert).order_by(Alert.issued_at.desc())\\n    if active_only:s=s.where(Alert.valid_until>utcnow())\\n    return page(db,s,limit,offset)\\n@app.get(\\\"/alerts/{iid}\\\",response_model=AlertOut)\\ndef alert_get(iid:int,db:Db): return get(db,Alert,iid)\\n@app.post(\\\"/alerts\\\",response_model=AlertOut,status_code=201)\\ndef alert_create(d:AlertIn,db:Db,u:Staff):\\n    area=d.area.model_dump(mode=\\\"json\\\")\\n    item=Alert(alert_type=d.alert_type.value,valid_until=as_utc(d.valid_until),description=d.description,safety_instructions=INSTRUCTIONS[d.alert_type.value],area=area,author_id=u.id)\\n    db.add(item); db.flush()\\n    for sub in db.scalars(select(LocationSubscription).where(LocationSubscription.enabled.is_(True))).yield_per(500):\\n        if in_polygon(sub.longitude,sub.latitude,area):\\n            db.add(Notification(user_id=sub.user_id,alert_id=item.id,message=f\\\"{d.alert_type.value}: {d.description[:430]}\\\"))\\n    db.commit(); return item\\n\\n@app.put(\\\"/subscriptions/me\\\",response_model=SubscriptionOut)\\ndef subscription(d:SubscriptionIn,db:Db,u:Current):\\n    item=db.scalar(select(LocationSubscription).where(LocationSubscription.user_id==u.id))\\n    if not item:item=LocationSubscription(user_id=u.id); db.add(item)\\n    item.longitude=d.longitude; item.latitude=d.latitude; item.enabled=d.enabled; item.updated_at=utcnow(); db.commit(); return item\\n@app.get(\\\"/notifications\\\",response_model=list[NotificationOut])\\ndef notifications(db:Db,u:Current,unread_only:bool=False,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    s=select(Notification).where(Notification.user_id==u.id).order_by(Notification.created_at.desc())\\n    if unread_only:s=s.where(Notification.read_at.is_(None))\\n    return page(db,s,limit,offset)\\n@app.post(\\\"/notifications/{iid}/read\\\",response_model=NotificationOut)\\ndef notification_read(iid:int,db:Db,u:Current):\\n    item=db.scalar(select(Notification).where(Notification.id==iid,Notification.user_id==u.id))\\n    if not item:raise HTTPException(404,\\\"Notification not found\\\")\\n    item.read_at=item.read_at or utcnow(); db.commit(); return item\\n\\n@app.post(\\\"/reports\\\",response_model=ReportOut,status_code=201)\\ndef report_create(d:ReportIn,db:Db,u:Current):\\n    item=WeatherReport(**d.model_dump(),user_id=u.id); item.image_url=http_url(item.image_url); item.event_at=as_utc(item.event_at); db.add(item); db.commit(); return item\\n@app.get(\\\"/reports/me\\\",response_model=list[ReportOut])\\ndef report_mine(db:Db,u:Current,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    return page(db,select(WeatherReport).where(WeatherReport.user_id==u.id).order_by(WeatherReport.created_at.desc()),limit,offset)\\n@app.get(\\\"/admin/reports\\\",response_model=list[ReportOut])\\ndef report_list(db:Db,_:Staff,report_status:ReportStatus|None=None,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):\\n    s=select(WeatherReport).order_by(WeatherReport.created_at.desc())\\n    if report_status:s=s.where(WeatherReport.review_status==report_status.value)\\n    return page(db,s,limit,offset)\\n@app.patch(\\\"/admin/reports/{iid}/review\\\",response_model=ReportOut)\\ndef report_review(iid:int,d:ReviewIn,db:Db,u:Staff):\\n    item=get(db,WeatherReport,iid)\\n    if item.review_status!=ReportStatus.PENDING.value:raise HTTPException(409,\\\"Already reviewed\\\")\\n    item.review_status=d.review_status.value; item.review_notes=d.review_notes; item.reviewer_id=u.id; item.reviewed_at=utcnow(); db.commit(); return item\\n\\n@app.get(\\\"/education\\\",response_model=list[EducationOut])\\ndef education_list(db:Db,limit:int=Query(50,ge=1,le=100),offset:int=Query(0,ge=0)):return page(db,select(EducationArticle).order_by(EducationArticle.created_at.desc()),limit,offset)\\n@app.get(\\\"/education/{iid}\\\",response_model=EducationOut)\\ndef education_get(iid:int,db:Db):return get(db,EducationArticle,iid)\\n@app.post(\\\"/education\\\",response_model=EducationOut,status_code=201)\\ndef education_create(d:EducationIn,db:Db,u:Staff):\\n    item=EducationArticle(**d.model_dump(),author_id=u.id);media(item);db.add(item);db.commit();return item\\n@app.patch(\\\"/education/{iid}\\\",response_model=EducationOut)\\ndef education_update(iid:int,d:EducationPatch,db:Db,_:Staff):\\n    item=get(db,EducationArticle,iid); values=d.model_dump(exclude_unset=True)\\n    if any(values.get(k) is None for k in (\\\"title\\\",\\\"body\\\",\\\"reference_url\\\") if k in values): raise HTTPException(422,\\\"Required content cannot be null\\\")\\n    for k,v in values.items():setattr(item,k,v)\\n    media(item);item.updated_at=utcnow();db.commit();return item\\n@app.delete(\\\"/education/{iid}\\\",status_code=204)\\ndef education_delete(iid:int,db:Db,_:Staff):\\n    db.delete(get(db,EducationArticle,iid));db.commit();return Response(status_code=204)\\n\",\"tests/test_api.py\":\"import importlib, os\\nfrom datetime import UTC,datetime,timedelta\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nos.environ.update(DATABASE_URL=\\\"sqlite:///./test_alerta.db\\\",APP_SECRET_KEY=\\\"test-secret-key-long-enough\\\",EXPOSE_DEV_TOKENS=\\\"true\\\",AUTO_CREATE_TABLES=\\\"true\\\",BOOTSTRAP_OWNER_NAME=\\\"Owner\\\",BOOTSTRAP_OWNER_EMAIL=\\\"owner@example.com\\\",BOOTSTRAP_OWNER_PASSWORD=\\\"Owner!123\\\")\\nm=importlib.import_module(\\\"app.main\\\")\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef client():\\n    m.Base.metadata.drop_all(m.engine)\\n    with TestClient(m.app) as c: yield c\\n    m.Base.metadata.drop_all(m.engine)\\n\\ndef H(t): return {\\\"Authorization\\\":f\\\"Bearer {t}\\\"}\\ndef login(c,email,password): return c.post(\\\"/auth/login-json\\\",json={\\\"email\\\":email,\\\"password\\\":password}).json()[\\\"access_token\\\"]\\ndef owner(c): return login(c,\\\"owner@example.com\\\",\\\"Owner!123\\\")\\ndef register(c,email,name=\\\"User\\\",password=\\\"Strong!1\\\"):\\n    r=c.post(\\\"/auth/register\\\",json={\\\"name\\\":name,\\\"email\\\":email,\\\"password\\\":password}); assert r.status_code==202,r.text\\n    assert c.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":r.json()[\\\"development_token\\\"]}).status_code==200\\n    return login(c,email,password)\\ndef make_met(c,email):\\n    token=register(c,email,\\\"Meteorologist\\\"); uid=c.get(\\\"/users/me\\\",headers=H(token)).json()[\\\"id\\\"]\\n    assert c.patch(f\\\"/admin/users/{uid}\\\",headers=H(owner(c)),json={\\\"role\\\":\\\"METEOROLOGIST\\\"}).status_code==200\\n    return login(c,email,\\\"Strong!1\\\")\\n\\ndef test_end_to_end(client):\\n    user=register(client,\\\"e2e-user@example.com\\\")\\n    met=make_met(client,\\\"e2e-met@example.com\\\")\\n    assert client.post(\\\"/news\\\",headers=H(met),json={\\\"title\\\":\\\"Update\\\",\\\"description\\\":\\\"Verified information\\\",\\\"reference_url\\\":\\\"https://example.org/source\\\"}).status_code==201\\n    polygon={\\\"type\\\":\\\"Polygon\\\",\\\"coordinates\\\":[[[-47,-24],[-46,-24],[-46,-23],[-47,-23],[-47,-24]]]}\\n    assert client.put(\\\"/subscriptions/me\\\",headers=H(user),json={\\\"longitude\\\":-46.6,\\\"latitude\\\":-23.5}).status_code==200\\n    a=client.post(\\\"/alerts\\\",headers=H(met),json={\\\"alert_type\\\":\\\"TORNADO\\\",\\\"valid_until\\\":(datetime.now(UTC)+timedelta(hours=1)).isoformat(),\\\"description\\\":\\\"Rotating storm\\\",\\\"area\\\":polygon})\\n    assert a.status_code==201,a.text\\n    assert client.get(\\\"/notifications\\\",headers=H(user)).json()[0][\\\"alert_id\\\"]==a.json()[\\\"id\\\"]\\n    assert client.patch(f\\\"/alerts/{a.json()['id']}\\\",headers=H(met),json={}).status_code==405\\n    f=client.post(\\\"/forecasts\\\",headers=H(met),json={\\\"valid_until\\\":(datetime.now(UTC)+timedelta(hours=2)).isoformat(),\\\"severity\\\":\\\"HIGH\\\",\\\"description\\\":\\\"Initial\\\",\\\"area\\\":polygon})\\n    assert f.status_code==201,f.text\\n    fid=f.json()[\\\"id\\\"]\\n    assert client.patch(f\\\"/forecasts/{fid}\\\",headers=H(met),json={\\\"description\\\":\\\"Updated\\\"}).status_code==200\\n    assert client.delete(f\\\"/forecasts/{fid}\\\",headers=H(met)).status_code==409\\n    with m.SessionLocal() as db:\\n        item=db.get(m.Forecast,fid); item.issued_at=datetime.now(UTC)-timedelta(minutes=31); db.commit()\\n    assert client.patch(f\\\"/forecasts/{fid}\\\",headers=H(met),json={\\\"description\\\":\\\"Late\\\"}).status_code==409\\n    assert client.delete(f\\\"/forecasts/{fid}\\\",headers=H(met)).status_code==204\\n    report=client.post(\\\"/reports\\\",headers=H(user),json={\\\"description\\\":\\\"Large hail\\\",\\\"location_name\\\":\\\"Mongagua\\\",\\\"longitude\\\":-46.62,\\\"latitude\\\":-24.09,\\\"event_at\\\":datetime.now(UTC).isoformat()})\\n    assert report.status_code==201,report.text\\n    assert client.patch(f\\\"/admin/reports/{report.json()['id']}/review\\\",headers=H(met),json={\\\"review_status\\\":\\\"VERIFIED\\\",\\\"review_notes\\\":\\\"Checked\\\"}).status_code==200\\n\\ndef test_patch_nulls_are_validation_errors(client):\\n    met=make_met(client,\\\"patch-met@example.com\\\")\\n    polygon={\\\"type\\\":\\\"Polygon\\\",\\\"coordinates\\\":[[[-47,-24],[-46,-24],[-46,-23],[-47,-23],[-47,-24]]]}\\n    f=client.post(\\\"/forecasts\\\",headers=H(met),json={\\\"valid_until\\\":(datetime.now(UTC)+timedelta(hours=2)).isoformat(),\\\"severity\\\":\\\"HIGH\\\",\\\"description\\\":\\\"Valid\\\",\\\"area\\\":polygon})\\n    assert f.status_code==201\\n    assert client.patch(f\\\"/forecasts/{f.json()['id']}\\\",headers=H(met),json={\\\"severity\\\":None}).status_code==422\\n    n=client.post(\\\"/news\\\",headers=H(met),json={\\\"title\\\":\\\"Valid\\\",\\\"description\\\":\\\"Valid\\\",\\\"reference_url\\\":\\\"https://example.org/source\\\"})\\n    assert client.patch(f\\\"/news/{n.json()['id']}\\\",headers=H(met),json={\\\"title\\\":None}).status_code==422\\n    assert client.patch(f\\\"/news/{n.json()['id']}\\\",headers=H(met),json={\\\"reference_url\\\":None}).status_code==422\\n\\ndef test_user_cannot_access_staff_route(client):\\n    user=register(client,\\\"rbac-user@example.com\\\")\\n    assert client.get(\\\"/admin/users\\\",headers=H(user)).status_code==403\\n\\ndef test_new_token_invalidates_old_and_is_single_use(client):\\n    first=client.post(\\\"/auth/register\\\",json={\\\"name\\\":\\\"Pending\\\",\\\"email\\\":\\\"pending@example.com\\\",\\\"password\\\":\\\"Strong!1\\\"}).json()[\\\"development_token\\\"]\\n    second=client.post(\\\"/auth/resend-verification\\\",json={\\\"email\\\":\\\"pending@example.com\\\"}).json()[\\\"development_token\\\"]\\n    assert client.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":first}).status_code==400\\n    assert client.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":second}).status_code==200\\n    assert client.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":second}).status_code==400\\n    reset1=client.post(\\\"/auth/forgot-password\\\",json={\\\"email\\\":\\\"pending@example.com\\\"}).json()[\\\"development_token\\\"]\\n    reset2=client.post(\\\"/auth/forgot-password\\\",json={\\\"email\\\":\\\"pending@example.com\\\"}).json()[\\\"development_token\\\"]\\n    assert client.post(\\\"/auth/reset-password\\\",json={\\\"token\\\":reset1,\\\"new_password\\\":\\\"Newpass!1\\\"}).status_code==400\\n    assert client.post(\\\"/auth/reset-password\\\",json={\\\"token\\\":reset2,\\\"new_password\\\":\\\"Newpass!1\\\"}).status_code==200\\n    assert client.post(\\\"/auth/reset-password\\\",json={\\\"token\\\":reset2,\\\"new_password\\\":\\\"Again!12\\\"}).status_code==400\\n\\ndef test_verification_token_is_bound_to_current_email(client):\\n    old=client.post(\\\"/auth/register\\\",json={\\\"name\\\":\\\"Rename\\\",\\\"email\\\":\\\"before@example.com\\\",\\\"password\\\":\\\"Strong!1\\\"}).json()[\\\"development_token\\\"]\\n    found=client.get(\\\"/admin/users\\\",headers=H(owner(client)),params={\\\"q\\\":\\\"before@example.com\\\"}).json()\\n    assert len(found)==1\\n    assert client.patch(f\\\"/admin/users/{found[0]['id']}\\\",headers=H(owner(client)),json={\\\"email\\\":\\\"after@example.com\\\"}).status_code==200\\n    assert client.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":old}).status_code==400\\n    current=client.post(\\\"/auth/resend-verification\\\",json={\\\"email\\\":\\\"after@example.com\\\"}).json()[\\\"development_token\\\"]\\n    assert client.post(\\\"/auth/verify-email\\\",json={\\\"token\\\":current}).status_code==200\\n\",\"README.md\":\"# Alerta Tempestade Backend\\n\\nBackend-only API derived from the supplied TCC PDF. Python 3.11+, FastAPI and SQLAlchemy; SQLite is the default and PostgreSQL is supported through DATABASE_URL; provide a complete URL-encoded DATABASE_URL when credentials contain reserved URL characters.\\n\\n## Start\\n\\n1. Run this generator: python alerta_tempestade_backend_generator.py\\n2. cd alerta-tempestade-backend\\n3. python -m venv .venv\\n4. Activate it and run: pip install -e \\\".[test]\\\"\\n5. Copy .env.example to .env and replace APP_SECRET_KEY.\\n6. uvicorn app.main:app --reload\\n7. Open http://localhost:8000/docs\\n8. Run: pytest\\n\\nDocker Compose provides a PostgreSQL development environment.\\n\\n## Contract\\n\\nPublic read routes: /news, /forecasts, /alerts and /education.\\nAuthentication: /auth/register, /auth/verify-email, /auth/login-json, /auth/forgot-password and /auth/reset-password.\\nProtected areas: /users/me, /subscriptions/me, /notifications and /reports.\\nMeteorologist areas: content writes, forecast/alert creation, report review and ordinary-user search/management.\\nThe PDF conflicts on role promotion (RF02 says owner-only while RF05/RF06 imply meteorologists); this implementation uses the safer rule that only OWNER changes roles. Bearer JWTs are invalidated after password/role changes.\\n\\nGeoJSON positions are [longitude, latitude]. Client timestamps require a timezone. OpenAPI is generated at /openapi.json. Readiness is available at /ready.\\n\\n## Explicit assumptions\\n\\nThe PDF permits forecast editing only in the first 30 minutes and describes deletion after 30 minutes; both statements are implemented literally. Alerts have no update/delete routes. User deletion is soft deletion to retain referential history. Alert notification is an opt-in current point and a durable in-app inbox. News requires a reference URL. Media is represented by validated HTTP(S) URLs until the team chooses object storage. Severity is LOW, MODERATE, HIGH or EXTREME because the PDF does not enumerate levels. OSM rendering is frontend work. No CEMADEN/radar API is fabricated without a concrete provider contract, so this deliverable is the core application MVP rather than the final live-radar integration.\\n\\n## Production gaps\\n\\nSMTP STARTTLS email delivery is implemented; configure SMTP_HOST and SMTP_FROM before setting EXPOSE_DEV_TOKENS=false. Development-token exposure must never be enabled on a publicly reachable deployment. Replace automatic schema creation with reviewed Alembic migrations. Add rate limiting and a background push/email provider. Use PostGIS for large, self-intersecting or antimeridian-crossing polygons. Keep secrets outside source control.\\n\"}")
root = Path("alerta-tempestade-backend")
